update public.pooja_steps set
  instruction_en = 'Tap your temples gently with the knuckles of both hands while reciting. The first verse is the general invocation said before any undertaking; the second is to Ganesha himself.',
  instruction_ta = 'இரு கைகளின் நெரிக்கும் விரல் மூட்டுகளால் நெற்றிப் பொட்டுகளில் மெதுவாகத் தட்டியபடி பாராயணம் செய்யவும். முதல் ஸ்லோகம் எந்தக் காரியத்தின் தொடக்கத்திலும் சொல்லப்படும் பொது வணக்கம்; இரண்டாவது விநாயகருக்கே உரியது.',
  mantra_sanskrit = 'शुक्लाम्बरधरं विष्णुं शशिवर्णं चतुर्भुजम् ।
प्रसन्नवदनं ध्यायेत् सर्वविघ्नोपशान्तये ॥
अगजानन पद्मार्कं गजाननमहर्निशम् ।
अनेकदं तं भक्तानां एकदन्तमुपास्महे ॥',
  mantra_tamil = 'ஶுக்லாம்பரதரம் விஷ்ணும் ஶஶிவர்ணம் சதுர்புஜம் ।
ப்ரஸந்நவதநம் த்யாயேத் ஸர்வவிக்நோபஶாந்தயே ॥
அகஜாநந பத்மார்கம் கஜாநநமஹர்நிஶம் ।
அநேகதம் தம் பக்தாநாம் ஏகதந்தமுபாஸ்மஹே ॥',
  mantra_translit = 'śuklāmbaradharaṃ viṣṇuṃ śaśivarṇaṃ caturbhujam ।
prasannavadanaṃ dhyāyet sarvavighnopaśāntaye ॥
agajānana padmārkaṃ gajānanamaharniśam ।
anekadaṃ taṃ bhaktānāṃ ekadantamupāsmahe ॥',
