where pooja_id = 'ganesha_standard' and step_title_en = 'Kalasha Pooja';

-- --- varalakshmi_vratham / Kalasha Pooja
update public.pooja_steps set
  instruction_en = 'Put sandal, kumkumam and akshatai on the vessel, fill it with water, and rest your right hand over its mouth while reciting. The verses seat Vishnu at the mouth, Rudra at the neck and Brahma at the base, then call the seven rivers into the water. At the end sprinkle that water on the pooja materials, on the deity and on yourself — that sprinkling is what the whole step is for.',
  instruction_ta = 'கலசத்தில் சந்தனம், குங்குமம், அக்ஷதை இட்டு, ஜலம் நிரப்பி, வலது கையை அதன் வாயின் மேல் வைத்தபடி பாராயணம் செய்யவும். ஸ்லோகங்கள் வாயில் விஷ்ணுவையும், கழுத்தில் ருத்திரனையும், அடியில் பிரம்மனையும் நிலைபெறச் செய்து, பின் ஏழு நதிகளையும் அந்த ஜலத்தில் ஆவாஹனம் செய்கின்றன. இறுதியில் அந்த ஜலத்தை பூஜைப் பொருட்கள் மீதும், சுவாமியின் மீதும், உங்கள் மீதும் தெளிக்கவும் — இந்தப் ப்ரோக்ஷணமே இந்தப் படியின் நோக்கம்.',
  mantra_sanskrit = 'कलशे गन्ध पुष्पाक्षतैरभ्यर्च्य ।
कलशे उदकं पूरयित्वा ।
कलशस्योपरि हस्तं निधाय ।
कलशस्य मुखे विष्णुः कण्ठे रुद्रः समाश्रितः ।
मूले त्वस्य स्थितो ब्रह्मा मध्ये मातृगणाः स्मृता ॥
कुक्षौ तु सागराः सर्वे सप्तद्वीपा वसुन्धरा ।
ऋग्वेदोऽथ यजुर्वेदो सामवेदो ह्यथर्वणः ॥
अङ्गैश्च सहिताः सर्वे कलशाम्बु समाश्रिताः ।
ॐ आकलशेषु धावति पवित्रे परिषिच्यते ।
उक्थैर्यज्ञेषु वर्धते ।
आपो वा इदं सर्वं विश्वा भूतान्यापः
प्राणा वा आपः पशव आपोऽन्नमापोऽमृतमापः
सम्राडापो विराडापः स्वराडापश्छन्दांस्यापो
ज्योतींष्यापो यजूंष्यापः सत्यमापः
सर्वा देवता आपो भूर्भुवः सुवराप ओम् ॥
गङ्गे च यमुने चैव गोदावरी सरस्वती ।
नर्मदे सिन्धु कावेरी जलेऽस्मिन् सन्निधिं कुरु ॥
कावेरी तुङ्गभद्रा च कृष्णवेणी च गौतमी ।
भागीरथीति विख्याताः पञ्चगङ्गाः प्रकीर्तिताः ॥
आयान्तु श्री वरलक्ष्मी पूजार्थं मम दुरितक्षयकारकाः ।
ॐ ॐ ॐ कलशोदकेन पूजा द्रव्याणि सम्प्रोक्ष्य,
देवं सम्प्रोक्ष्य, आत्मानं च सम्प्रोक्ष्य ॥',
  mantra_tamil = 'கலஶே கந்த புஷ்பாக்ஷதைரப்யர்ச்ய ।
கலஶே உதகம் பூரயித்வா ।
கலஶஸ்யோபரி ஹஸ்தம் நிதாய ।
கலஶஸ்ய முகே விஷ்ணு꞉ கண்டே ருத்ர꞉ ஸமாஶ்ரித꞉ ।
மூலே த்வஸ்ய ஸ்திதோ ப்ரஹ்மா மத்யே மாத்ருகணா꞉ ஸ்ம்ருதா ॥
குக்ஷௌ து ஸாகரா꞉ ஸர்வே ஸப்தத்வீபா வஸுந்தரா ।
ருக்வேதோத யஜுர்வேதோ ஸாமவேதோ ஹ்யதர்வண꞉ ॥
அங்கைஶ்ச ஸஹிதா꞉ ஸர்வே கலஶாம்பு ஸமாஶ்ரிதா꞉ ।
ஓம் ஆகலஶேஷு தாவதி பவித்ரே பரிஷிச்யதே ।
உக்தைர்யஜ்ஞேஷு வர்ததே ।
ஆபோ வா இதம் ஸர்வம் விஶ்வா பூதாந்யாப꞉
ப்ராணா வா ஆப꞉ பஶவ ஆபோந்நமாபோம்ருதமாப꞉
ஸம்ராடாபோ விராடாப꞉ ஸ்வராடாபஶ்சந்தாம்ஸ்யாபோ
ஜ்யோதீம்ஷ்யாபோ யஜூம்ஷ்யாப꞉ ஸத்யமாப꞉
ஸர்வா தேவதா ஆபோ பூர்புவ꞉ ஸுவராப ஓம் ॥
கங்கே ச யமுநே சைவ கோதாவரீ ஸரஸ்வதீ ।
நர்மதே ஸிந்து காவேரீ ஜலேஸ்மிந் ஸந்நிதிம் குரு ॥
காவேரீ துங்கபத்ரா ச க்ருஷ்ணவேணீ ச கௌதமீ ।
பாகீரதீதி விக்யாதா꞉ பஞ்சகங்கா꞉ ப்ரகீர்திதா꞉ ॥
ஆயாந்து ஶ்ரீ வரலக்ஷ்மீ பூஜார்தம் மம துரிதக்ஷயகாரகா꞉ ।
ஓம் ஓம் ஓம் கலஶோதகேந பூஜா த்ரவ்யாணி ஸம்ப்ரோக்ஷ்ய,
தேவம் ஸம்ப்ரோக்ஷ்ய, ஆத்மாநம் ச ஸம்ப்ரோக்ஷ்ய ॥',
  mantra_translit = 'kalaśe gandha puṣpākṣatairabhyarcya ।
kalaśe udakaṃ pūrayitvā ।
kalaśasyopari hastaṃ nidhāya ।
kalaśasya mukhe viṣṇuḥ kaṇṭhe rudraḥ samāśritaḥ ।
mūle tvasya sthito brahmā madhye mātṛgaṇāḥ smṛtā ॥
kukṣau tu sāgarāḥ sarve saptadvīpā vasundharā ।
ṛgvedo''tha yajurvedo sāmavedo hyatharvaṇaḥ ॥
aṅgaiśca sahitāḥ sarve kalaśāmbu samāśritāḥ ।
oṃ ākalaśeṣu dhāvati pavitre pariṣicyate ।
ukthairyajñeṣu vardhate ।
āpo vā idaṃ sarvaṃ viśvā bhūtānyāpaḥ
prāṇā vā āpaḥ paśava āpo''nnamāpo''mṛtamāpaḥ
samrāḍāpo virāḍāpaḥ svarāḍāpaśchandāṃsyāpo
jyotīṃṣyāpo yajūṃṣyāpaḥ satyamāpaḥ
sarvā devatā āpo bhūrbhuvaḥ suvarāpa om ॥
gaṅge ca yamune caiva godāvarī sarasvatī ।
narmade sindhu kāverī jale''smin sannidhiṃ kuru ॥
kāverī tuṅgabhadrā ca kṛṣṇaveṇī ca gautamī ।
bhāgīrathīti vikhyātāḥ pañcagaṅgāḥ prakīrtitāḥ ॥
āyāntu śrī varalakṣmī pūjārthaṃ mama duritakṣayakārakāḥ ।
oṃ oṃ oṃ kalaśodakena pūjā dravyāṇi samprokṣya,
devaṃ samprokṣya, ātmānaṃ ca samprokṣya ॥',
  source_ref = 'StotraNidhi, Puja Vidhanam (Poorvangam – Smartha Paddhati), stotranidhi.com/en/puja-vidhanam-poorvangam-in-english/, round-trip verified IAST->Devanagari by scripts/build-purvangam-and-upacharas.mjs. Svara marks are stripped; the app does not render them yet.',
