-- --- ganesha_standard / Ghanta Pooja
update public.pooja_steps set
  instruction_en = 'Worship the bell with akshatai, then ring it with the left hand. The verse says plainly what the sound is for: to call the devas and to send away what should not be here.',
  instruction_ta = 'மணியை அக்ஷதையால் பூஜித்து, பின் இடது கையால் அடிக்கவும். அந்த ஒலி எதற்கு என்பதை ஸ்லோகமே சொல்கிறது: தேவர்களை அழைக்கவும், இருக்கக் கூடாதவற்றை விலக்கவும்.',
  mantra_sanskrit = 'ॐ जयध्वनि मन्त्रमातः स्वाहा ।
घण्टदेवताभ्यो नमः ।
सकलोपचार पूजार्थे अक्षतान् समर्पयामि ।
आगमार्थं तु देवानां गमनार्थं तु राक्षसाम् ।
घण्टारवं करोम्यादौ देवताह्वान लाञ्छनम् ॥
इति घण्टानादं कृत्वा ॥',
  mantra_tamil = 'ஓம் ஜயத்வநி மந்த்ரமாத꞉ ஸ்வாஹா ।
கண்டதேவதாப்யோ நம꞉ ।
ஸகலோபசார பூஜார்தே அக்ஷதாந் ஸமர்பயாமி ।
ஆகமார்தம் து தேவாநாம் கமநார்தம் து ராக்ஷஸாம் ।
கண்டாரவம் கரோம்யாதௌ தேவதாஹ்வாந லாஞ்சநம் ॥
இதி கண்டாநாதம் க்ருத்வா ॥',
  mantra_translit = 'oṃ jayadhvani mantramātaḥ svāhā ।
ghaṇṭadevatābhyo namaḥ ।
sakalopacāra pūjārthe akṣatān samarpayāmi ।
āgamārthaṃ tu devānāṃ gamanārthaṃ tu rākṣasām ।
ghaṇṭāravaṃ karomyādau devatāhvāna lāñchanam ॥
iti ghaṇṭānādaṃ kṛtvā ॥',
  source_ref = 'StotraNidhi, Puja Vidhanam (Poorvangam – Smartha Paddhati), stotranidhi.com/en/puja-vidhanam-poorvangam-in-english/, round-trip verified IAST->Devanagari by scripts/build-purvangam-and-upacharas.mjs. Svara marks are stripped; the app does not render them yet. Corrects two spellings that were in production in both poojas: देवताव्हान for देवताह्वान (āhvāna, invocation — vhāna is not a word), and घन्टा for घण्टा. The paddhati also reads ghaṇṭāravaṃ karomyādau where the earlier text had kuru ghaṇṭāravaṃ tatra; both readings circulate and the published one is used.',
  verified_by = null,
  verified_at = null,
  updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Ghanta Pooja';

