-- --- ganesha_standard / Padyam & Arghyam
update public.pooja_steps set
  instruction_en = 'Four offerings of water, each into a separate empty bowl, never back into the panchapatra: arghyam for the hands, padyam for the feet, achamaniyam for sipping, and the madhuparkam of curd, milk, honey and ghee for a guest of honour.',
  instruction_ta = 'நான்கு ஜல சமர்ப்பணங்கள் — ஒவ்வொன்றையும் தனி வெறும் பாத்திரத்தில் விடவும், பஞ்சபாத்திரத்திற்குள் மீண்டும் விடக் கூடாது: கைகளுக்கு அர்க்யம், திருவடிகளுக்கு பாத்யம், ஆசமனத்திற்கு ஆசமனீயம், சிறந்த விருந்தினருக்குரிய தயிர், பால், தேன், நெய் கலந்த மதுபர்க்கம்.',
  mantra_sanskrit = 'गौरीपुत्र नमस्तेऽस्तु शंकरप्रियनंदन ।
गृहाणार्घ्यं मया दत्तं गंधपुष्पाक्षतैर्युतम् ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः अर्घ्यं समर्पयामि ।
गजवक्त्र नमस्तेऽस्तु सर्वाभीष्टप्रदायक ।
भक्त्या पाद्यं मया दत्तं गृहाण द्विरदानन ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः पाद्यं समर्पयामि ।
अनाथनाथ सर्वज्ञ गीर्वाणवरपूजित ।
गृहाणाचमनं देव तुभ्यं दत्तं मया प्रभो ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः आचमनीयं समर्पयामि ।
दधिक्षीरसमायुक्तं मध्वाज्येन समन्वितम् ।
मधुपर्कं गृहाणेदं गजवक्त्र नमोऽस्तु ते ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः मधुपर्कं समर्पयामि ।',
  mantra_tamil = 'கௌரீபுத்ர நமஸ்தேஸ்து ஶம்கரப்ரியநம்தந ।
க்ருஹாணார்க்யம் மயா தத்தம் கம்தபுஷ்பாக்ஷதைர்யுதம் ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ அர்க்யம் ஸமர்பயாமி ।
கஜவக்த்ர நமஸ்தேஸ்து ஸர்வாபீஷ்டப்ரதாயக ।
பக்த்யா பாத்யம் மயா தத்தம் க்ருஹாண த்விரதாநந ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ பாத்யம் ஸமர்பயாமி ।
அநாதநாத ஸர்வஜ்ஞ கீர்வாணவரபூஜித ।
க்ருஹாணாசமநம் தேவ துப்யம் தத்தம் மயா ப்ரபோ ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ ஆசமநீயம் ஸமர்பயாமி ।
ததிக்ஷீரஸமாயுக்தம் மத்வாஜ்யேந ஸமந்விதம் ।
மதுபர்கம் க்ருஹாணேதம் கஜவக்த்ர நமோஸ்து தே ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ மதுபர்கம் ஸமர்பயாமி ।',
  mantra_translit = 'gaurīputra namaste''stu śaṃkarapriyanaṃdana ।
gṛhāṇārghyaṃ mayā dattaṃ gaṃdhapuṣpākṣatairyutam ॥
oṃ śrī siddhivināyaka svāmine namaḥ arghyaṃ samarpayāmi ।
gajavaktra namaste''stu sarvābhīṣṭapradāyaka ।
bhaktyā pādyaṃ mayā dattaṃ gṛhāṇa dviradānana ॥
oṃ śrī siddhivināyaka svāmine namaḥ pādyaṃ samarpayāmi ।
anāthanātha sarvajña gīrvāṇavarapūjita ।
gṛhāṇācamanaṃ deva tubhyaṃ dattaṃ mayā prabho ॥
oṃ śrī siddhivināyaka svāmine namaḥ ācamanīyaṃ samarpayāmi ।
dadhikṣīrasamāyuktaṃ madhvājyena samanvitam ।
madhuparkaṃ gṛhāṇedaṃ gajavaktra namo''stu te ॥
oṃ śrī siddhivināyaka svāmine namaḥ madhuparkaṃ samarpayāmi ।',
  source_ref = 'StotraNidhi Sri Siddhi Vinayaka Vrata Kalpam (Telugu), round-trip verified Telugu->Devanagari by scripts/build-purvangam-and-upacharas.mjs. Replaces a bare samarpayami tag that carried no verse.',
  verified_by = null,
  verified_at = null,
  updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Padyam & Arghyam';

-- --- ganesha_standard / Snanam & Vastram
update public.pooja_steps set
  instruction_en = 'Bathe the idol in panchamritam, then in clean water, and offer achamaniyam after. Then the vastram, and the single poonal that is on the samagri list for this pooja. Akshatai or a flower stands in for cloth if you have none.',
  instruction_ta = 'விக்கிரகத்திற்கு பஞ்சாமிர்தத்தால் அபிஷேகம் செய்து, பின் சுத்த ஜலத்தால் ஸ்நானம் செய்வித்து, பிறகு ஆசமனீயம் சமர்ப்பிக்கவும். பின் வஸ்திரமும், இந்தப் பூஜைக்கான சாமக்ரி பட்டியலில் உள்ள ஒற்றைப் பூணூலும். துணி இல்லையெனில் அக்ஷதையோ புஷ்பமோ அதற்குப் பதிலாகும்.',
  mantra_sanskrit = 'स्नानं पंचामृतैर्देव गृहाण गणनायक ।
अनाथनाथ सर्वज्ञ गीर्वाणगणपूजित ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः पंचामृत स्नानं समर्पयामि ।
गंगादिसर्वतीर्थेभ्य आहृतैरमलैर्जलैः ।
स्नानं कुरुष्य भगवन्नुमापुत्र नमोऽस्तु ते ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः शुद्धोदक स्नानं समर्पयामि ।
स्नानानंतरं आचमनीयं समर्पयामि ।
रक्तवस्त्रद्वयं चारु देवयोग्यं च मंगळम् ।
शुभप्रद गृहाण त्वं लंबोदर हरात्मज ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः वस्त्रयुग्मं समर्पयामि ।
राजतं ब्रह्मसूत्रं च कांचनं चोत्तरीयकम् ।
गृहाण देव सर्वज्ञ भक्तानामिष्टदायक ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः यज्ञोपवीतं समर्पयामि ।',
  mantra_tamil = 'ஸ்நாநம் பம்சாம்ருதைர்தேவ க்ருஹாண கணநாயக ।
அநாதநாத ஸர்வஜ்ஞ கீர்வாணகணபூஜித ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ பம்சாம்ருத ஸ்நாநம் ஸமர்பயாமி ।
கம்காதிஸர்வதீர்தேப்ய ஆஹ்ருதைரமலைர்ஜலை꞉ ।
ஸ்நாநம் குருஷ்ய பகவந்நுமாபுத்ர நமோஸ்து தே ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ ஶுத்தோதக ஸ்நாநம் ஸமர்பயாமி ।
ஸ்நாநாநம்தரம் ஆசமநீயம் ஸமர்பயாமி ।
ரக்தவஸ்த்ரத்வயம் சாரு தேவயோக்யம் ச மம்களம் ।
ஶுபப்ரத க்ருஹாண த்வம் லம்போதர ஹராத்மஜ ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ வஸ்த்ரயுக்மம் ஸமர்பயாமி ।
ராஜதம் ப்ரஹ்மஸூத்ரம் ச காம்சநம் சோத்தரீயகம் ।
க்ருஹாண தேவ ஸர்வஜ்ஞ பக்தாநாமிஷ்டதாயக ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ யஜ்ஞோபவீதம் ஸமர்பயாமி ।',
  mantra_translit = 'snānaṃ paṃcāmṛtairdeva gṛhāṇa gaṇanāyaka ।
anāthanātha sarvajña gīrvāṇagaṇapūjita ॥
oṃ śrī siddhivināyaka svāmine namaḥ paṃcāmṛta snānaṃ samarpayāmi ।
gaṃgādisarvatīrthebhya āhṛtairamalairjalaiḥ ।
snānaṃ kuruṣya bhagavannumāputra namo''stu te ॥
oṃ śrī siddhivināyaka svāmine namaḥ śuddhodaka snānaṃ samarpayāmi ।
snānānaṃtaraṃ ācamanīyaṃ samarpayāmi ।
raktavastradvayaṃ cāru devayogyaṃ ca maṃgal̤am ।
śubhaprada gṛhāṇa tvaṃ laṃbodara harātmaja ॥
oṃ śrī siddhivināyaka svāmine namaḥ vastrayugmaṃ samarpayāmi ।
rājataṃ brahmasūtraṃ ca kāṃcanaṃ cottarīyakam ।
gṛhāṇa deva sarvajña bhaktānāmiṣṭadāyaka ॥
oṃ śrī siddhivināyaka svāmine namaḥ yajñopavītaṃ samarpayāmi ।',
  source_ref = 'StotraNidhi Sri Siddhi Vinayaka Vrata Kalpam (Telugu), round-trip verified Telugu->Devanagari by scripts/build-purvangam-and-upacharas.mjs. Replaces a bare samarpayami tag that carried no verse.',
  verified_by = null,
  verified_at = null,
  updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Snanam & Vastram';

-- --- ganesha_standard / Gandham, Kumkumam & Pushpam
update public.pooja_steps set
  instruction_en = 'Sandal paste first, then kumkumam and akshatai, then the flowers. The pushpam verse asks for the twenty-one leaves by name, which is what the Patra Pooja a few steps later offers one at a time.',
  instruction_ta = 'முதலில் சந்தனம், பின் குங்குமமும் அக்ஷதையும், பிறகு புஷ்பங்கள். புஷ்ப ஸ்லோகம் இருபத்தொரு பத்திரங்களையும் பெயர் சொல்லிக் கேட்கிறது — அவற்றையே சில படிகளுக்குப் பின் வரும் பத்ர பூஜையில் ஒவ்வொன்றாகச் சமர்ப்பிக்கிறோம்.',
  mantra_sanskrit = 'चंदनागरु कर्पूर कस्तूरी कुंकुमान्वितम् ।
विलेपनं सुरश्रेष्ठ प्रीत्यर्थं प्रतिगृह्यताम् ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः श्रीगंधान् धारयामि ।
अक्षतान् धवळान् दिव्यान् शालीयांस्तंडुलान् शुभान् ।
गृहाण परमानंद शंभुपुत्र नमोऽस्तु ते ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः अलंकरणार्थं अक्षतान् समर्पयामि ।
सुगंधानि च पुष्पाणि जातीकुंदमुखानि च ।
एकविंशतिपत्राणि संगृहाण नमोऽस्तु ते ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः पुष्पैः पूजयामि ।',
  mantra_tamil = 'சம்தநாகரு கர்பூர கஸ்தூரீ கும்குமாந்விதம் ।
விலேபநம் ஸுரஶ்ரேஷ்ட ப்ரீத்யர்தம் ப்ரதிக்ருஹ்யதாம் ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ ஶ்ரீகம்தாந் தாரயாமி ।
அக்ஷதாந் தவளாந் திவ்யாந் ஶாலீயாம்ஸ்தம்டுலாந் ஶுபாந் ।
க்ருஹாண பரமாநம்த ஶம்புபுத்ர நமோஸ்து தே ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ அலம்கரணார்தம் அக்ஷதாந் ஸமர்பயாமி ।
ஸுகம்தாநி ச புஷ்பாணி ஜாதீகும்தமுகாநி ச ।
ஏகவிம்ஶதிபத்ராணி ஸம்க்ருஹாண நமோஸ்து தே ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ புஷ்பை꞉ பூஜயாமி ।',
  mantra_translit = 'caṃdanāgaru karpūra kastūrī kuṃkumānvitam ।
vilepanaṃ suraśreṣṭha prītyarthaṃ pratigṛhyatām ॥
oṃ śrī siddhivināyaka svāmine namaḥ śrīgaṃdhān dhārayāmi ।
