-- --- assert -------------------------------------------------------------------
do $$
declare n int;
begin
  -- The misspellings must be gone everywhere, not just where this migration looked.
  select count(*) into n from public.pooja_steps
   where mantra_sanskrit like '%व्हान%' or mantra_sanskrit like '%घन्ट%'
      or mantra_translit like '%vhāna%' or mantra_translit like '%ghanṭ%';
  if n > 0 then raise exception '% steps still carry the ghanta misspellings', n; end if;
  select count(*) into n from public.pooja_steps
   where step_title_en = 'Ghanta Pooja' and mantra_sanskrit like '%देवताह्वान%';
  if n <> 2 then raise exception 'expected both ghanta steps corrected, found %', n; end if;
  -- Kalasha without the samprokshana is the step with its point removed.
  select count(*) into n from public.pooja_steps
   where step_title_en = 'Kalasha Pooja'
     and mantra_sanskrit like '%कलशस्य मुखे%' and mantra_sanskrit like '%सम्प्रोक्ष्य%';
  if n <> 2 then raise exception 'expected both kalasha steps filled out, found %', n; end if;
  -- No turmeric cone in the Chaturthi avahanam.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard' and step_title_en = 'Avahanam & Asanam' and mantra_sanskrit like '%हरिद्रा%';
  if n > 0 then raise exception 'Ganesha is still invoked into a turmeric image'; end if;
  -- Only the Sankalpam may still be an unreviewed draft.
  select count(*) into n from public.pooja_steps
   where source_ref like '%Tamil draft, pending vaidika review%'
     and step_title_en <> 'Sankalpam';
  if n > 0 then raise exception '% steps other than Sankalpam are still drafts', n; end if;
end $$;

commit;

